CREATE TABLE schema_migrations(version INTEGER PRIMARY KEY, checksum TEXT NOT NULL);
CREATE TABLE store_metadata(name TEXT PRIMARY KEY, value BLOB NOT NULL);
CREATE TABLE tasks(task_id TEXT PRIMARY KEY, workspace_ref TEXT NOT NULL, state TEXT NOT NULL, version INTEGER NOT NULL CHECK(version>=0), contract BLOB NOT NULL, record BLOB NOT NULL);
CREATE TABLE events(task_id TEXT NOT NULL REFERENCES tasks(task_id), sequence INTEGER NOT NULL CHECK(sequence>=0), kind TEXT NOT NULL, created_at_ms INTEGER NOT NULL, payload BLOB NOT NULL, PRIMARY KEY(task_id,sequence));
CREATE TRIGGER events_no_update BEFORE UPDATE ON events BEGIN SELECT RAISE(ABORT,'events are append only'); END;
CREATE TRIGGER events_no_delete BEFORE DELETE ON events BEGIN SELECT RAISE(ABORT,'events are append only'); END;
CREATE TABLE blob_objects(digest TEXT PRIMARY KEY, plain_bytes INTEGER NOT NULL CHECK(plain_bytes>=0), stored_bytes INTEGER NOT NULL CHECK(stored_bytes>=0), created_at_ms INTEGER NOT NULL);
CREATE TABLE artifacts(artifact_id TEXT PRIMARY KEY, task_id TEXT NOT NULL REFERENCES tasks(task_id), digest TEXT NOT NULL REFERENCES blob_objects(digest), content_type TEXT NOT NULL, logical_type TEXT NOT NULL, schema_version TEXT NOT NULL, created_at_ms INTEGER NOT NULL, retain_until_ms INTEGER NOT NULL, legal_hold INTEGER NOT NULL DEFAULT 0 CHECK(legal_hold IN (0,1)), payload BLOB NOT NULL);
CREATE INDEX artifacts_task ON artifacts(task_id);
CREATE INDEX artifacts_digest ON artifacts(digest);
CREATE TABLE artifact_refs(owner_task_id TEXT NOT NULL REFERENCES tasks(task_id), owner_kind TEXT NOT NULL, owner_id TEXT NOT NULL, artifact_id TEXT NOT NULL REFERENCES artifacts(artifact_id), PRIMARY KEY(owner_kind,owner_id,artifact_id));
CREATE INDEX artifact_refs_artifact ON artifact_refs(artifact_id);
CREATE TRIGGER artifact_refs_owner BEFORE INSERT ON artifact_refs WHEN (SELECT task_id FROM artifacts WHERE artifact_id=NEW.artifact_id)<>NEW.owner_task_id BEGIN SELECT RAISE(ABORT,'artifact owner mismatch'); END;
CREATE TABLE invocations(invocation_id TEXT PRIMARY KEY, task_id TEXT NOT NULL REFERENCES tasks(task_id), tool_id TEXT NOT NULL, arguments_digest TEXT NOT NULL, idempotency_key TEXT, state TEXT NOT NULL, version INTEGER NOT NULL CHECK(version>=0), generation INTEGER NOT NULL CHECK(generation>=0), active_attempt_id TEXT, result_artifact_id TEXT REFERENCES artifacts(artifact_id), payload BLOB NOT NULL);
CREATE UNIQUE INDEX invocation_idempotency ON invocations(task_id,idempotency_key) WHERE idempotency_key IS NOT NULL;
CREATE INDEX invocations_task ON invocations(task_id,state);
CREATE TRIGGER invocation_result_owner BEFORE UPDATE OF result_artifact_id ON invocations WHEN NEW.result_artifact_id IS NOT NULL AND (SELECT task_id FROM artifacts WHERE artifact_id=NEW.result_artifact_id)<>NEW.task_id BEGIN SELECT RAISE(ABORT,'invocation artifact owner mismatch'); END;
CREATE TABLE attempts(attempt_id TEXT PRIMARY KEY, invocation_id TEXT NOT NULL REFERENCES invocations(invocation_id), task_id TEXT NOT NULL REFERENCES tasks(task_id), number INTEGER NOT NULL CHECK(number>0), generation INTEGER NOT NULL CHECK(generation>=0), state TEXT NOT NULL, version INTEGER NOT NULL CHECK(version>=0), payload BLOB NOT NULL, UNIQUE(invocation_id,number));
CREATE UNIQUE INDEX one_active_attempt ON attempts(invocation_id) WHERE state IN ('prepared','dispatched','running','outcome_unknown');
CREATE INDEX attempts_task ON attempts(task_id);
CREATE TABLE checkpoints(checkpoint_id TEXT PRIMARY KEY, task_id TEXT NOT NULL REFERENCES tasks(task_id), task_version INTEGER NOT NULL CHECK(task_version>=0), artifact_id TEXT NOT NULL REFERENCES artifacts(artifact_id), created_at_ms INTEGER NOT NULL, payload BLOB NOT NULL);
CREATE INDEX checkpoints_task ON checkpoints(task_id,task_version);
CREATE TRIGGER checkpoint_owner BEFORE INSERT ON checkpoints WHEN (SELECT task_id FROM artifacts WHERE artifact_id=NEW.artifact_id)<>NEW.task_id BEGIN SELECT RAISE(ABORT,'checkpoint artifact owner mismatch'); END;
PRAGMA user_version=1;
